<?php $alquileres=array_values(array_filter($tarifas, fn(array $t): bool => $t['tipo']==='alquiler')); $extras=array_values(array_filter($tarifas, fn(array $t): bool => $t['tipo']==='extra')); ?>
<div class="page-header"><h1>Tarifas</h1><p>Precios transparentes, sin sorpresas. El precio final se confirma al aprobar tu solicitud.</p></div>
<?php if (!$tarifas): ?><p class="empty-state">Las tarifas estarán disponibles próximamente.</p><?php endif; ?>
<?php if ($alquileres): ?><div class="tarifas-grid"><?php foreach ($alquileres as $tarifa): ?><div class="tarifa-card <?= $tarifa['destacada'] ? 'tarifa-destacada' : '' ?>"><?php if ($tarifa['destacada']): ?><div class="tarifa-badge">Más popular</div><?php endif; ?><div class="tarifa-header"><h2><?= e($tarifa['nombre']) ?></h2><div class="tarifa-precio">Desde <strong><?= e($tarifa['precio']) ?></strong><span><?= e($tarifa['unidad']) ?></span></div></div><?php $items=preg_split('/\r\n|\r|\n/', (string)$tarifa['descripcion'], -1, PREG_SPLIT_NO_EMPTY); if ($items): ?><ul class="tarifa-features"><?php foreach ($items as $item): ?><li><?= e($item) ?></li><?php endforeach; ?></ul><?php endif; ?><a href="/catalogo.php" class="btn <?= $tarifa['destacada'] ? 'btn-primary' : 'btn-secondary' ?>">Ver modelos</a></div><?php endforeach; ?></div><?php endif; ?>
<?php if ($extras): ?><div class="tarifas-extra"><h2>Servicios adicionales</h2><table class="tabla-extras"><thead><tr><th>Servicio</th><th>Precio</th></tr></thead><tbody><?php foreach ($extras as $extra): ?><tr><td><?= e($extra['nombre']) ?></td><td><?= e($extra['precio']) ?> <?= e($extra['unidad']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<div class="tarifas-nota"><h3>¿Cómo funciona?</h3><ol><li>Elige tu máquina en el <a href="/catalogo.php">catálogo</a> y comprueba la <a href="/calendario.php">disponibilidad</a>.</li><li>Rellena el <a href="/solicitud.php">formulario de solicitud</a> con tus dudas o necesidades.</li><li>Recibirás confirmación en menos de 24 h.</li></ol></div>
